package exporter

import (
	"bytes"
	"fmt"
	"regexp"
	"sort"
	"strings"

	netgrabv1 "netgrab/internal/model/netgrabv1"
)

// TerraformExporter renders the device set as Terraform configuration for the
// NetBox provider (e-breuninger/netbox). It emits manufacturers, device types,
// devices, interfaces, IP addresses and VLANs, wired together by Terraform
// resource references.
//
// Two facts NetBox requires but a device config does not carry — the site and
// the device role — are exposed as input variables (netbox_site_id,
// netbox_device_role_id) so the generated file is apply-ready once the operator
// supplies them. Interface media types are a best-effort mapping (documented
// inline) that may need adjustment per hardware.
type TerraformExporter struct{}

func (TerraformExporter) Format() string    { return "tf" }
func (TerraformExporter) Extension() string { return "tf" }

func (TerraformExporter) Export(set *netgrabv1.DeviceConfigSet) ([]byte, error) {
	v := ToView(set)
	var b strings.Builder

	b.WriteString(`# Generated by netgrab — NetBox Terraform (provider: e-breuninger/netbox).
#
# Supply the two facts a device config cannot carry before applying:
#   terraform apply -var 'netbox_site_id=1' -var 'netbox_device_role_id=1'
#
# Interface "type" is a best-effort media mapping; adjust per hardware as needed.

terraform {
  required_providers {
    netbox = {
      source = "e-breuninger/netbox"
    }
  }
}

variable "netbox_site_id" {
  type        = number
  description = "NetBox site id every generated device is placed in."
}

variable "netbox_device_role_id" {
  type        = number
  description = "NetBox device role id assigned to every generated device."
}

`)

	// --- manufacturers (unique vendors) ---
	mfgIDs := map[string]string{} // vendor -> tf resource addr fragment
	var vendors []string
	for _, d := range v.Devices {
		if d.Vendor != "" {
			if _, ok := mfgIDs[d.Vendor]; !ok {
				mfgIDs[d.Vendor] = tfID("mfg", d.Vendor)
				vendors = append(vendors, d.Vendor)
			}
		}
	}
	sort.Strings(vendors)
	for _, vn := range vendors {
		writeResource(&b, "netbox_manufacturer", mfgIDs[vn], []attr{{"name", hclStr(vn)}})
	}

	// --- device types (unique vendor+model) ---
	type dtKey struct{ vendor, model string }
	dtIDs := map[dtKey]string{}
	var dtOrder []dtKey
	for _, d := range v.Devices {
		if d.Vendor == "" {
			continue
		}
		model := d.Model
		if model == "" {
			model = d.Vendor + "-generic"
		}
		k := dtKey{d.Vendor, model}
		if _, ok := dtIDs[k]; !ok {
			dtIDs[k] = tfID("dt", d.Vendor, model)
			dtOrder = append(dtOrder, k)
		}
	}
	for _, k := range dtOrder {
		writeResource(&b, "netbox_device_type", dtIDs[k], []attr{
			{"model", hclStr(k.model)},
			{"manufacturer_id", "netbox_manufacturer." + mfgIDs[k.vendor] + ".id"},
			{"slug", hclStr(slugify(k.vendor + "-" + k.model))},
		})
	}

	// --- global VLANs (dedup by vid across the fleet) ---
	vlanSeen := map[uint32]bool{}
	var vlanOrder []VlanView
	for _, d := range v.Devices {
		for _, vl := range d.Vlans {
			if vl.ID == 0 || vlanSeen[vl.ID] {
				continue
			}
			vlanSeen[vl.ID] = true
			vlanOrder = append(vlanOrder, vl)
		}
	}
	sort.Slice(vlanOrder, func(i, j int) bool { return vlanOrder[i].ID < vlanOrder[j].ID })
	for _, vl := range vlanOrder {
		name := vl.Name
		if name == "" {
			name = fmt.Sprintf("vlan%d", vl.ID)
		}
		writeResource(&b, "netbox_vlan", tfID("vlan", fmt.Sprint(vl.ID)), []attr{
			{"vid", fmt.Sprint(vl.ID)},
			{"name", hclStr(name)},
		})
	}

	// --- devices + interfaces + ip addresses ---
	devSeen := map[string]bool{}
	for _, d := range v.Devices {
		if d.Hostname == "" {
			continue
		}
		devAddr := tfID("dev", d.Hostname)
		// Guard against duplicate hostnames producing clashing resource names.
		if devSeen[devAddr] {
			devAddr = tfID("dev", d.Hostname, d.SHA256[:min(8, len(d.SHA256))])
		}
		devSeen[devAddr] = true

		model := d.Model
		if model == "" {
			model = d.Vendor + "-generic"
		}
		dtAddr := dtIDs[dtKey{d.Vendor, model}]

		devAttrs := []attr{{"name", hclStr(d.Hostname)}}
		if dtAddr != "" {
			devAttrs = append(devAttrs, attr{"device_type_id", "netbox_device_type." + dtAddr + ".id"})
		}
		devAttrs = append(devAttrs,
			attr{"role_id", "var.netbox_device_role_id"},
			attr{"site_id", "var.netbox_site_id"},
			attr{"status", hclStr("active")},
		)
		if d.Serial != "" {
			devAttrs = append(devAttrs, attr{"serial", hclStr(d.Serial)})
		}
		writeResource(&b, "netbox_device", devAddr, devAttrs)

		for _, i := range d.Interfaces {
			ifAddr := tfID("if", d.Hostname, i.Name)
			ifAttrs := []attr{
				{"device_id", "netbox_device." + devAddr + ".id"},
				{"name", hclStr(i.Name)},
				{"type", hclStr(netboxIfType(i.Type))},
				{"enabled", fmt.Sprintf("%t", i.Enabled)},
			}
			if i.MTU > 0 {
				ifAttrs = append(ifAttrs, attr{"mtu", fmt.Sprint(i.MTU)})
			}
			if i.Description != "" {
				ifAttrs = append(ifAttrs, attr{"description", hclStr(i.Description)})
			}
			if i.MacAddress != "" {
				ifAttrs = append(ifAttrs, attr{"mac_address", hclStr(strings.ToUpper(i.MacAddress))})
			}
			writeResource(&b, "netbox_device_interface", ifAddr, ifAttrs)

			for idx, addr := range i.IPAddresses {
				ipAddr := tfID("ip", d.Hostname, i.Name, fmt.Sprint(idx))
				writeResource(&b, "netbox_ip_address", ipAddr, []attr{
					{"ip_address", hclStr(addr)},
					{"status", hclStr("active")},
					{"object_type", hclStr("dcim.interface")},
					{"interface_id", "netbox_device_interface." + ifAddr + ".id"},
				})
			}
		}
	}

	return []byte(b.String()), nil
}

// attr is one HCL attribute: key plus an already-rendered value (hclStr for
// strings, a bare expression for refs/numbers/bools).
type attr struct{ key, val string }

// writeResource emits one HCL resource block with its attributes' "=" signs
// aligned, so the output is stable under `terraform fmt`.
func writeResource(b *strings.Builder, rtype, name string, attrs []attr) {
	maxw := 0
	for _, a := range attrs {
		if len(a.key) > maxw {
			maxw = len(a.key)
		}
	}
	fmt.Fprintf(b, "resource %q %q {\n", rtype, name)
	for _, a := range attrs {
		fmt.Fprintf(b, "  %-*s = %s\n", maxw, a.key, a.val)
	}
	b.WriteString("}\n\n")
}

// netboxIfType maps netgrab's coarse interface type to a NetBox interface type
// slug. NetBox requires a valid slug; physical media is not knowable from a
// text config, so Ethernet ports default to a common 1G copper type and virtual
// kinds map to "virtual"/"lag". Operators should refine these post-import.
func netboxIfType(t string) string {
	switch t {
	case "loopback", "vlan", "tunnel", "bridge":
		return "virtual"
	case "lag":
		return "lag"
	default: // ethernet, mgmt, wlan, ""
		return "1000base-t"
	}
}

var tfIDStrip = regexp.MustCompile(`[^a-z0-9]+`)

// tfID builds a safe, unique-ish Terraform resource local name from parts.
func tfID(parts ...string) string {
	joined := strings.Join(parts, "_")
	joined = strings.ToLower(joined)
	joined = tfIDStrip.ReplaceAllString(joined, "_")
	joined = strings.Trim(joined, "_")
	if joined == "" {
		return "x"
	}
	// Terraform identifiers must start with a letter or underscore.
	if joined[0] >= '0' && joined[0] <= '9' {
		joined = "_" + joined
	}
	return joined
}

// slugify builds a NetBox slug (lowercase, hyphen-separated).
func slugify(s string) string {
	s = strings.ToLower(s)
	s = tfIDStrip.ReplaceAllString(s, "-")
	return strings.Trim(s, "-")
}

// hclStr renders a Go string as a double-quoted HCL string literal.
func hclStr(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\n", `\n`, "\t", `\t`, "\r", "")
	var buf bytes.Buffer
	buf.WriteByte('"')
	buf.WriteString(r.Replace(s))
	buf.WriteByte('"')
	return buf.String()
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
